package com.drivique.api.service;
import com.drivique.api.dto.*; import com.drivique.api.exception.*; import com.drivique.api.model.*; import com.drivique.api.repository.*; import java.time.Instant; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CashPaymentService { private final ReservationRepository reservations; private final RentalContractRepository contracts; private final PaymentRepository payments; private final PaymentMethodRepository methods; private final PaymentStatusRepository paymentStatuses; private final ReservationStatusRepository reservationStatuses; private final CurrencyRepository currencies; private final UserRepository users;
 public CashPaymentService(ReservationRepository reservations,RentalContractRepository contracts,PaymentRepository payments,PaymentMethodRepository methods,PaymentStatusRepository paymentStatuses,ReservationStatusRepository reservationStatuses,CurrencyRepository currencies,UserRepository users){this.reservations=reservations;this.contracts=contracts;this.payments=payments;this.methods=methods;this.paymentStatuses=paymentStatuses;this.reservationStatuses=reservationStatuses;this.currencies=currencies;this.users=users;}
 @Transactional public CashPaymentConfirmationResponseDTO confirm(CashPaymentConfirmationRequestDTO input,String email){Reservation reservation=reservations.findByCashPaymentCodeIgnoreCase(input.cashPaymentCode().trim()).orElseThrow(()->new ResourceNotFoundException("Código de pago en efectivo no encontrado")); if(reservation.getCashPaymentBranch()==null||!reservation.getCashPaymentBranch().allowsCashPayment())throw new ConflictException("La sede de la reserva no permite pagos en efectivo."); if(reservation.getCashPaymentExpiresAt()!=null&&reservation.getCashPaymentExpiresAt().isBefore(Instant.now()))throw new ConflictException("El código de pago en efectivo está vencido."); RentalContract contract=contracts.findByReservationId(reservation.getId()).orElseThrow(()->new ResourceNotFoundException("Contrato no encontrado")); if(payments.existsByGatewayProviderAndGatewayReference("EFECTIVO_CAJA",reservation.getCashPaymentCode()))throw new ConflictException("El pago en efectivo ya fue confirmado."); User cashier=users.findByEmailIgnoreCaseAndDeletedAtIsNull(email).orElseThrow(()->new ResourceNotFoundException("Cajero no encontrado")); Payment payment=new Payment(contract,methods.findByCodeIgnoreCaseAndActiveTrue("CASH").orElseThrow(()->new ResourceNotFoundException("Método CASH no encontrado")),paymentStatuses.findByCodeIgnoreCase("APPROVED").orElseThrow(()->new ResourceNotFoundException("Estado APPROVED no encontrado")),"EFECTIVO_CAJA",reservation.getCashPaymentCode(),contract.getBaseAmount().add(contract.getSecurityDeposit()),currencies.findByCodeIgnoreCaseAndActiveTrue("COP").orElseThrow(()->new ResourceNotFoundException("Moneda COP no encontrada")),cashier); payment.setPaidAt(Instant.now()); Payment saved=payments.saveAndFlush(payment); reservation.setStatus(reservationStatuses.findByCodeIgnoreCase("CONFIRMED").orElseThrow(()->new ResourceNotFoundException("Estado CONFIRMED no encontrado"))); return new CashPaymentConfirmationResponseDTO(saved.getId(),saved.getGatewayReference(),saved.getAmount(),"APPROVED",Instant.now()); }
}
